DocsMask.exampleCardCustomization0Code:
import { getCardType, useViraMask } from "@virastack/mask"

const { card } = useViraMask(form, { card: "card" })
const type = getCardType(form.watch("card")) // "visa" | "mastercard" | "amex" | "troy" | "unknown"

DocsMask.exampleCardCustomization1Code:
const { card, expiry } = useViraMask(form, {
  card: { preset: "card", onComplete: () => form.setFocus("expiry") },
  expiry: "expiry",
})

DocsMask.exampleCvvCustomization0Code:
const { card, cvv } = useViraMask(form, {
  card: "card",
  cvv: { preset: "cvv", from: "card" },
})

DocsMask.exampleCurrencyCustomization0Code:
const form = useForm({ defaultValues: { currency: "TRY", price: "" } })

const { price } = useViraMask(form, {
  price: { preset: "currency", from: "currency" },
})

<select {...form.register("currency")}>
  <option>TRY</option>
  <option>USD</option>
  <option>EUR</option>
</select>
<input {...price} />

DocsMask.exampleCurrencyCustomization1Code:
useViraMask(form, {
  usd: { preset: "currency", currency: "USD" },                      // $1,234.56
  euro: { preset: "currency", currency: { code: "EUR", locale: "de-DE" } }, // 1.234,56 €
  limit: { preset: "currency", country: "TR", currency: { min: 10, max: 5000 } },
})

DocsMask.exampleNumberCustomization0Code:
useViraMask(form, {
  quantity: { preset: "number", number: { min: 1, max: 99 } },
  weight: { preset: "number", number: { scale: 2, locale: "en-US" } },
})

DocsMask.exampleDateCustomization0Code:
useViraMask(form, {
  birthDate: { preset: "date", date: { max: "today", minAge: 18 } },
})

DocsMask.exampleCustomCustomization0Code:
// masks.ts — shared by the client and the server
import { definePreset } from "@virastack/mask/server"

export const plate = definePreset("plate", {
  mask: "99 a[aa] 99[99]",
  transform: "uppercase",
})

// form
useViraMask(form, { plate })

DocsMask.exampleNumberCustomization1Code:
useViraMask(form, {
  amount: { preset: "number", country: "TR", number: { scale: 2 } }, // 1.234,56
})

DocsMask.examplePhoneCustomization0Code:
useViraMask(form, {
  phone: { preset: "phone", country: "TR" },
})
// typed as +90 555…, 0555… or 555… → (555) 123 45 67
// form.watch("phone") → "5551234567"

DocsMask.examplePhoneCustomization1Code:
useViraMask(form, {
  phone: { preset: "phone", country: "TR", output: "masked" },
})
// form.watch("phone") → "(555) 123 45 67"

